import React, { useMemo, useState } from 'react';
import BackspaceOutlinedIcon from '@mui/icons-material/BackspaceOutlined';
import KeyboardReturnIcon from '@mui/icons-material/KeyboardReturn';
import { GameCopy } from './gameCopy';
import { LetterResult, scoreWordleGuess, WordList, wordleLetters } from './wordleEngine';

/** Same feedback rules as the board. A later grey never erases an earlier green. */
export function keyboardFeedback(answer: string, guesses: string[]) {
  const result: Record<string, LetterResult> = {};
  const rank = { absent: 0, present: 1, correct: 2 };
  for (const guess of guesses) {
    const marks = scoreWordleGuess(answer, guess);
    wordleLetters(guess).forEach((letter, index) => {
      if (!result[letter] || rank[marks[index]] > rank[result[letter]]) {
        result[letter] = marks[index];
      }
    });
  }
  return result;
}

export default function WordleKeyboard({
  words,
  answer,
  guesses,
  onLetter,
  onDelete,
  onEnter,
  canSubmit,
  t,
  native,
  onToggleNative,
}: {
  words: WordList;
  answer: string;
  guesses: string[];
  onLetter: (letter: string) => void;
  onDelete: () => void;
  onEnter: () => void;
  canSubmit: boolean;
  t: GameCopy;
  native: boolean;
  onToggleNative: () => void;
}) {
  const [syllable, setSyllable] = useState('');
  const [page, setPage] = useState(0);
  const chinese = words.locale === 'zh-hans';
  const feedback = useMemo(() => keyboardFeedback(answer, guesses), [answer, guesses]);
  const accents = useMemo(
    () =>
      [...new Set(words.allowedGuesses.flatMap(wordleLetters))]
        .filter((letter) => !/^[A-Z]$/.test(letter))
        .sort(),
    [words],
  );
  const [accentBase, setAccentBase] = useState('A');
  const candidates =
    chinese && syllable
      ? Object.entries(words.input?.pinyin || {})
          .filter(([, pinyin]) => pinyin === syllable)
          .map(([char]) => char)
      : [];
  const accentGroups = [
    ...new Set(
      accents.map((letter) =>
        letter.normalize('NFD').replace(/\p{M}/gu, '').replace('Đ', 'D').replace('ẞ', 'S'),
      ),
    ),
  ];
  const visibleAccents =
    accents.length > 20
      ? accents.filter(
          (letter) =>
            letter.normalize('NFD').replace(/\p{M}/gu, '').replace('Đ', 'D').replace('ẞ', 'S') ===
            accentBase,
        )
      : accents;
  const add = (letter: string) => {
    if (chinese) {
      setSyllable((current) => (current + letter.toLowerCase()).slice(0, 8));
      setPage(0);
    } else {
      onLetter(letter);
    }
  };
  const remove = () => {
    if (syllable) {
      setSyllable((current) => current.slice(0, -1));
      setPage(0);
    } else {
      onDelete();
    }
  };
  const key = (letter: string) => (
    <button
      type="button"
      key={letter}
      data-letter={chinese ? undefined : feedback[letter]}
      onPointerDown={(e) => e.preventDefault()}
      onClick={() => add(letter)}
      aria-label={`${letter}${feedback[letter] && !chinese ? `: ${t[feedback[letter] === 'correct' ? 'correctPosition' : feedback[letter] === 'present' ? 'otherPosition' : 'absentLetter']}` : ''}`}
    >
      {letter}
    </button>
  );
  return (
    <div className="wordle-keyboard" aria-label={t.keyboard} role="group">
      {!native && (
        <>
          {chinese && (
            <div className="wordle-composition">
              <span aria-live="polite">{syllable || t.pinyinHelp}</span>
              <div className="wordle-candidates">
                {candidates.slice(page * 8, page * 8 + 8).map((char) => (
                  <button
                    type="button"
                    key={char}
                    data-letter={feedback[char]}
                    onPointerDown={(e) => e.preventDefault()}
                    onClick={() => {
                      onLetter(char);
                      setSyllable('');
                      setPage(0);
                    }}
                  >
                    {char}
                  </button>
                ))}
                {candidates.length > 8 && (
                  <button
                    type="button"
                    aria-label={t.next}
                    onClick={() =>
                      setPage((current) => (current + 1) % Math.ceil(candidates.length / 8))
                    }
                  >
                    ›
                  </button>
                )}
              </div>
            </div>
          )}
          {['QWERTYUIOP', 'ASDFGHJKL', 'ZXCVBNM'].map((row, index) => (
            <div className="wordle-key-row" key={row}>
              {index === 2 && (
                <button
                  className="wordle-key-wide"
                  type="button"
                  aria-label={t.backspace}
                  onPointerDown={(e) => e.preventDefault()}
                  onClick={remove}
                >
                  <BackspaceOutlinedIcon />
                </button>
              )}
              {row.split('').map(key)}
              {index === 2 && (
                <button
                  className="wordle-key-wide"
                  type="button"
                  aria-label={t.submit}
                  disabled={!canSubmit || !!syllable}
                  onClick={onEnter}
                >
                  <KeyboardReturnIcon />
                </button>
              )}
            </div>
          ))}
          {!chinese && accents.length > 0 && (
            <div className="wordle-accent-keys">
              {accents.length > 20 && (
                <div className="wordle-key-row">
                  {accentGroups.map((base) => (
                    <button
                      type="button"
                      key={base}
                      aria-pressed={accentBase === base}
                      onClick={() => {
                        setAccentBase(base);
                        setPage(0);
                      }}
                    >
                      {base}…
                    </button>
                  ))}
                </div>
              )}
              <div className="wordle-key-row">
                {visibleAccents.slice(page * 8, page * 8 + 8).map(key)}
                {visibleAccents.length > 8 && (
                  <button
                    type="button"
                    aria-label={t.next}
                    onClick={() =>
                      setPage((current) => (current + 1) % Math.ceil(visibleAccents.length / 8))
                    }
                  >
                    ›
                  </button>
                )}
              </div>
            </div>
          )}
        </>
      )}
      <button
        type="button"
        className="wordle-keyboard-toggle"
        onClick={() => {
          setSyllable('');
          onToggleNative();
        }}
      >
        {native ? t.customKeyboard : t.nativeKeyboard}
      </button>
    </div>
  );
}
