import React, { useId } from 'react';
import GameSheet from './GameSheet';
import { GameCopy } from './gameCopy';
import { wordleLetters } from './wordleEngine';

const HELP_ART = {
  blank: '/games/blank-illustration.webp',
  flashcards: '/games/flashcards-illustration.webp',
} as const;

function WordleLesson({
  t,
  examples = ['GRACE', 'PEACE', 'STONE'],
}: {
  t: GameCopy;
  examples?: string[];
}) {
  const rows = [
    {
      word: examples[0],
      marks: ['correct', '', '', '', ''] as const,
      focus: wordleLetters(examples[0])[0],
      caption: t.correctPosition,
    },
    {
      word: examples[1],
      marks: ['', 'present', '', '', ''] as const,
      focus: wordleLetters(examples[1])[1],
      caption: t.otherPosition,
    },
    {
      word: examples[2],
      marks: ['', '', 'absent', '', ''] as const,
      focus: wordleLetters(examples[2])[2],
      caption: t.absentLetter,
    },
  ];
  return (
    <div className="wordle-lesson">
      {rows.map((row) => (
        <div key={row.word}>
          <div className="wordle-example" aria-hidden="true">
            {wordleLetters(row.word).map((letter, index) => (
              <span
                className="wordle-cell"
                key={`${row.word}-${index}`}
                {...(row.marks[index] ? { 'data-letter': row.marks[index] } : {})}
              >
                {letter}
              </span>
            ))}
          </div>
          <p className="wordle-example-note">
            <strong>{row.focus}</strong> · {row.caption}
          </p>
        </div>
      ))}
    </div>
  );
}

export default function GameHelpDialog({
  open,
  onClose,
  onStart,
  t,
  game,
  children,
  examples,
  chinese = false,
  onExited,
}: {
  open: boolean;
  onClose: () => void;
  onStart?: () => void;
  t: GameCopy;
  game: 'wordle' | 'blank' | 'flashcards';
  children?: React.ReactNode;
  examples?: string[];
  chinese?: boolean;
  onExited?: () => void;
}) {
  const title = useId();
  const art =
    game === 'wordle' ? undefined : (
      <span className={`game-sheet-frame game-sheet-frame-${game}`}>
        <img src={HELP_ART[game]} alt="" width={768} height={512} />
      </span>
    );
  return (
    <GameSheet
      open={open}
      onClose={onClose}
      closeLabel={t.close}
      titleId={title}
      title={t.howToPlay}
      art={art}
      help
      onExited={onExited}
      footer={
        onStart && (
          <button className="game-sheet-action" type="button" onClick={onStart}>
            {t.start}
          </button>
        )
      }
    >
      <p className="game-sheet-lead">
        {game === 'wordle'
          ? chinese
            ? t.chineseHelp
            : t.englishHelp
          : game === 'blank'
            ? t.blankHelp
            : t.flashcardsHelp}
      </p>
      {game === 'wordle' && <WordleLesson t={t} examples={examples} />}
      {children}
      <hr className="game-sheet-rule" />
      <p className="game-sheet-note">{t.timerHelp}</p>
    </GameSheet>
  );
}
