import React from 'react';
import { Dialog, DialogContent } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import CloseIcon from '@mui/icons-material/Close';
import GameIconButton from './GameIconButton';
import { getModalSurface } from '../utils/modalSurface';

const sheetFont = '"Helvetica Neue", Helvetica, Arial, sans-serif';

export default function GameSheet({
  open,
  onClose,
  closeLabel,
  titleId,
  title,
  align = 'start',
  art,
  onExited,
  children,
  footer,
  help = false,
}: {
  open: boolean;
  onClose: () => void;
  closeLabel: string;
  titleId: string;
  title: string;
  align?: 'start' | 'center';
  art?: React.ReactNode;
  onExited?: () => void;
  children: React.ReactNode;
  footer?: React.ReactNode;
  help?: boolean;
}) {
  const theme = useTheme();
  const mode = theme.palette.mode;
  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="xs"
      fullWidth
      aria-labelledby={titleId}
      {...(onExited ? { TransitionProps: { onExited } } : {})}
      PaperProps={{
        className: `game-sheet game-sheet-${mode}${align === 'center' ? ' game-sheet-center' : ''}${help ? ' game-sheet-help' : ''}${footer ? ' game-sheet-has-footer' : ''}`,
        elevation: 0,
        sx: {
          ...getModalSurface(mode),
          fontFamily: sheetFont,
          maxWidth: 440,
        },
      }}
    >
      <span className="game-sheet-close">
        <GameIconButton label={closeLabel} onClick={onClose}>
          <CloseIcon />
        </GameIconButton>
      </span>
      <DialogContent
        className="games-page game-dialog game-sheet-body"
        data-theme={mode}
        sx={{ padding: '28px 28px 32px' }}
      >
        {art}
        <h2 className="game-sheet-title" id={titleId}>
          {title}
        </h2>
        {children}
      </DialogContent>
      {footer && (
        <div className="games-page game-dialog game-sheet-footer" data-theme={mode}>
          {footer}
        </div>
      )}
    </Dialog>
  );
}
