import { readerCatalogs as locales } from '../i18n/catalogs';
import en from '../i18n/locales/en.json';
import { gameTranslations } from './catalog';

export function gameCopy(translation: string, interfaceLocale?: keyof typeof locales) {
  const locale = gameTranslations.find((t) => t.id === translation)?.locale || 'en';
  const dictionary = locales[locale as keyof typeof locales] || en;
  return {
    t: (interfaceLocale ? locales[interfaceLocale] : dictionary).games,
    locale: locale === 'zh-hans' ? 'zh-Hans' : locale,
    bookName: (book: string): string => (dictionary.books as Record<string, string>)[book] || book,
  };
}
export type GameCopy = typeof en.games;
